func parsePath(path string) []string {
	var parts []string
	var b strings.Builder
	for i := 0; i < len(path); i++ {
		switch c := path[i]; c {
		case '.':
			if b.Len() > 0 { parts = append(parts, b.String()); b.Reset() }
		case '[':
			if b.Len() > 0 { parts = append(parts, b.String()); b.Reset() }
			j := strings.IndexByte(path[i:], ']')
			if j < 0 {
				b.WriteString(path[i:])
				i = len(path)
				continue
			}
			idx := path[i+1 : i+j]
			idx = strings.TrimSpace(idx)
			// strip quotes for map keys like ["a.b"]
			idx = strings.Trim(idx, `"'`)
			if idx != "" { parts = append(parts, idx) }
			i += j
		default:
			b.WriteByte(c)
		}
	}
	if b.Len() > 0 { parts = append(parts, b.String()) }
	return parts
}
