// Package mapfluent provides a small, dependency-free helper for working with
// arbitrary, dynamically shaped map[string]interface{} data through a fluent,
// chainable API.
//
// A Map wraps a single JSON-like value (usually an object decoded with
// encoding/json) and can navigate nested objects and arrays, mutate them, and
// convert leaf values to Go types, all while remaining safely chainable even
// when intermediate keys are missing.
//
//	doc, _ := mapfluent.FromJSON([]byte(`{"user":{"name":"Ada","langs":["go","c"]}}`))
//
//	name := doc.GetPath("user.name").String()        // "Ada"
//	first := doc.GetPath("user.langs[0]").String()   // "go"
//
//	doc.SetPath("user.active", true).
//		SetPath("user.name", "Ada Lovelace").
//		DeletePath("user.langs")
//
// Missing keys yield a nil value rather than a panic, so a chain can always be
// finished with a typed accessor to obtain a sensible zero value:
//
//	if doc.GetPath("user.missing.deep").Bool() {
//		// never runs
//	}
//
// Map values are reference types: a Map obtained with Get/GetPath shares the
// underlying nested map with its parent, so mutations propagate in both
// directions. Clone returns a fully independent deep copy.
package mapfluent

package mapfluent

import "sort"

// Map wraps an arbitrary JSON-like value and exposes a fluent, chainable API
// for reading and mutating nested map[string]interface{} data.
//
// The zero value is not usable directly; construct one with New, Wrap, or
// FromJSON. A *Map is safe for chaining: methods never return nil, so a call
// on a missing key still produces a usable (nil-valued) Map.
type Map struct {
	value interface{}
	found bool
}

// New returns a Map backed by the supplied object. With no argument (or a nil
// argument) it starts from an empty object. The supplied map is used directly,
// not copied.
func New(data ...map[string]interface{}) *Map {
	m := map[string]interface{}{}
	if len(data) > 0 && data[0] != nil {
		m = data[0]
	}
	return &Map{value: m, found: true}
}

// Wrap returns a Map around an arbitrary value, which may be an object, an
// array, a scalar, or nil.
func Wrap(value interface{}) *Map {
	return &Map{value: value, found: true}
}

// Clone returns a deep copy of the Map. Mutating the clone never affects the
// original, and vice versa.
func (m *Map) Clone() *Map {
	return &Map{value: deepClone(m.value), found: m.found}
}

// Value returns the underlying value.
func (m *Map) Value() interface{} {
	if m == nil {
		return nil
	}
	return m.value
}

// Interface is an alias for Value.
func (m *Map) Interface() interface{} {
	return m.Value()
}

// Raw is an alias for Value.
func (m *Map) Raw() interface{} {
	return m.Value()
}

// Object returns the underlying value if it is an object, otherwise nil.
func (m *Map) Object() map[string]interface{} {
	if m == nil {
		return nil
	}
	if obj, ok := m.value.(map[string]interface{}); ok {
		return obj
	}
	return nil
}

// Array returns the underlying value as a slice if it is an array, otherwise
// nil.
func (m *Map) Array() []interface{} {
	if m == nil {
		return nil
	}
	if arr, ok := m.value.([]interface{}); ok {
		return arr
	}
	return nil
}

// Exists reports whether the wrapped value was present. A present but
// explicitly nil value reports true; a missing key reports false.
func (m *Map) Exists() bool {
	return m != nil && m.found
}

// IsNil reports whether the wrapped value is nil.
func (m *Map) IsNil() bool {
	return m == nil || m.value == nil
}

// IsObject reports whether the wrapped value is an object.
func (m *Map) IsObject() bool {
	_, ok := m.Value().(map[string]interface{})
	return ok
}

// IsArray reports whether the wrapped value is an array.
func (m *Map) IsArray() bool {
	_, ok := m.Value().([]interface{})
	return ok
}

// Get returns the value of the given key, or of successive nested keys when
// several are supplied. Each argument is treated as a literal key.
func (m *Map) Get(keys ...string) *Map {
	value, ok := lookup(m.Value(), keys)
	return &Map{value: value, found: ok}
}

// GetPath is like Get but splits a single dotted path into keys, with optional
// zero-based array indexes written in brackets. For example "user.langs[0].name".
func (m *Map) GetPath(path string) *Map {
	return m.Get(parsePath(path)...)
}

// At is an alias for Get.
func (m *Map) At(keys ...string) *Map {
	return m.Get(keys...)
}

// Set assigns value to the top-level key and returns the receiver for
// chaining. If the Map is not currently an object it is replaced by a new one.
func (m *Map) Set(key string, value interface{}) *Map {
	root, _ := setPath(m.value, []string{key}, value)
	m.value = root
	m.found = true
	return m
}

// SetPath assigns value at the given dotted path, creating intermediate
// objects as needed, and returns the receiver for chaining.
func (m *Map) SetPath(path string, value interface{}) *Map {
	root, _ := setPath(m.value, parsePath(path), value)
	m.value = root
	m.found = true
	return m
}

// SetAll copies every key from src into the receiver at the top level and
// returns the receiver for chaining.
func (m *Map) SetAll(src map[string]interface{}) *Map {
	obj := m.object()
	for k, v := range src {
		obj[k] = v
	}
	return m
}

// Delete removes the top-level key and returns the receiver for chaining.
func (m *Map) Delete(key string) *Map {
	if root, ok := deletePath(m.value, []string{key}); ok {
		m.value = root
	}
	return m
}

// DeletePath removes the value at the given dotted path and returns the
// receiver for chaining.
func (m *Map) DeletePath(path string) *Map {
	if root, ok := deletePath(m.value, parsePath(path)); ok {
		m.value = root
	}
	return m
}

// Has reports whether the top-level key is present.
func (m *Map) Has(key string) bool {
	_, ok := lookup(m.Value(), []string{key})
	return ok
}

// HasPath reports whether the dotted path is present.
func (m *Map) HasPath(path string) bool {
	_, ok := lookup(m.value, parsePath(path))
	return ok
}

// Keys returns the sorted top-level keys of an object, or the string indexes
// of an array. It returns nil for any other value.
func (m *Map) Keys() []string {
	switch v := m.Value().(type) {
	case map[string]interface{}:
		keys := make([]string, 0, len(v))
		for k := range v {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		return keys
	case []interface{}:
		keys := make([]string, len(v))
		for i := range v {
			keys[i] = itoa(i)
		}
		return keys
	default:
		return nil
	}
}

// Len returns the number of elements in an object or array, zero otherwise.
func (m *Map) Len() int {
	switch v := m.Value().(type) {
	case map[string]interface{}:
		return len(v)
	case []interface{}:
		return len(v)
	default:
		return 0
	}
}

// Each calls fn for every top-level entry of an object in sorted key order.
// Iteration stops early when fn returns false. It returns the receiver for
// chaining.
func (m *Map) Each(fn func(key string, value *Map) bool) *Map {
	obj := m.Object()
	if obj == nil {
		return m
	}
	for _, key := range m.Keys() {
		if !fn(key, Wrap(obj[key])) {
			break
		}
	}
	return m
}

// Merge deep-merges the supplied maps into the receiver. Nested objects are
// merged recursively; all other values are replaced. It returns the receiver
// for chaining.
func (m *Map) Merge(others ...*Map) *Map {
	dst := m.object()
	for _, other := range others {
		if other == nil {
			continue
		}
		if src := other.Object(); src != nil {
			deepMerge(dst, src)
		}
	}
	return m
}

// object returns the underlying object, replacing the value with a new empty
// object if it is not already one.
func (m *Map) object() map[string]interface{} {
	if obj, ok := m.value.(map[string]interface{}); ok {
		return obj
	}
	obj := map[string]interface{}{}
	m.value = obj
	m.found = true
	return obj
}

package mapfluent

import (
	"strconv"
	"strings"
)

// parsePath splits a dotted path into individual keys or indexes. Brackets may
// be used for array indexes or for object keys that contain dots:
//
//	user.name        -> ["user", "name"]
//	items[0].id      -> ["items", "0", "id"]
//	meta["a.b"].c    -> ["meta", "a.b", "c"]
func parsePath(path string) []string {
	var (
		parts []string
		b     strings.Builder
	)
	flush := func() {
		if b.Len() > 0 {
			parts = append(parts, b.String())
			b.Reset()
		}
	}
	for i := 0; i < len(path); i++ {
		switch path[i] {
		case '.':
			flush()
		case '[':
			flush()
			end := strings.IndexByte(path[i:], ']')
			if end < 0 {
				b.WriteString(path[i+1:])
				i = len(path)
				continue
			}
			key := strings.TrimSpace(path[i+1 : i+end])
			key = strings.Trim(key, `"'`)
			if key != "" {
				parts = append(parts, key)
			}
			i += end
		default:
			b.WriteByte(path[i])
		}
	}
	flush()
	return parts
}

// lookup walks keys through nested objects and arrays, reporting whether the
// whole path was present.
func lookup(node interface{}, keys []string) (interface{}, bool) {
	cur := node
	for _, key := range keys {
		switch c := cur.(type) {
		case map[string]interface{}:
			v, ok := c[key]
			if !ok {
				return nil, false
			}
			cur = v
		case []interface{}:
			idx, err := strconv.Atoi(key)
			if err != nil || idx < 0 || idx >= len(c) {
				return nil, false
			}
			cur = c[idx]
		default:
			return nil, false
		}
	}
	return cur, true
}

// setPath assigns value at keys, returning the (possibly new) root and whether
// the assignment succeeded. Intermediate objects are created automatically and
// non-container values are overwritten to make room.
func setPath(node interface{}, keys []string, value interface{}) (interface{}, bool) {
	if len(keys) == 0 {
		return value, true
	}
	key := keys[0]

	switch c := node.(type) {
	case map[string]interface{}:
		if len(keys) == 1 {
			c[key] = value
			return c, true
		}
		child, ok := setPath(c[key], keys[1:], value)
		if !ok {
			return node, false
		}
		c[key] = child
		return c, true
	case []interface{}:
		idx, err := strconv.Atoi(key)
		if err != nil || idx < 0 {
			return node, false
		}
		if len(keys) == 1 {
			switch {
			case idx < len(c):
				c[idx] = value
				return c, true
			case idx == len(c):
				return append(c, value), true
			default:
				return node, false
			}
		}
		if idx >= len(c) {
			return node, false
		}
		child, ok := setPath(c[idx], keys[1:], value)
		if !ok {
			return node, false
		}
		c[idx] = child
		return c, true
	default:
		return setPath(map[string]interface{}{}, keys, value)
	}
}

// deletePath removes the value at keys, returning the (possibly new) root and
// whether anything was removed.
func deletePath(node interface{}, keys []string) (interface{}, bool) {
	if len(keys) == 0 {
		return node, false
	}
	key := keys[0]

	switch c := node.(type) {
	case map[string]interface{}:
		if len(keys) == 1 {
			if _, ok := c[key]; !ok {
				return node, false
			}
			delete(c, key)
			return c, true
		}
		child, ok := c[key]
		if !ok {
			return node, false
		}
		updated, ok := deletePath(child, keys[1:])
		if !ok {
			return node, false
		}
		c[key] = updated
		return c, true
	case []interface{}:
		idx, err := strconv.Atoi(key)
		if err != nil || idx < 0 || idx >= len(c) {
			return node, false
		}
		if len(keys) == 1 {
			return append(c[:idx:idx], c[idx+1:]...), true
		}
		updated, ok := deletePath(c[idx], keys[1:])
		if !ok {
			return node, false
		}
		c[idx] = updated
		return c, true
	default:
		return node, false
	}
}

// deepClone recursively copies objects and arrays.
func deepClone(value interface{}) interface{} {
	switch v := value.(type) {
	case map[string]interface{}:
		out := make(map[string]interface{}, len(v))
		for key, val := range v {
			out[key] = deepClone(val)
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, val := range v {
			out[i] = deepClone(val)
		}
		return out
	default:
		return value
	}
}

// deepMerge recursively merges src into dst.
func deepMerge(dst, src map[string]interface{}) {
	for key, srcVal := range src {
		if dstVal, ok := dst[key]; ok {
			dstObj, dstIsObj := dstVal.(map[string]interface{})
			srcObj, srcIsObj := srcVal.(map[string]interface{})
			if dstIsObj && srcIsObj {
				deepMerge(dstObj, srcObj)
				continue
			}
		}
		dst[key] = deepClone(srcVal)
	}
}

